"""Snap span edges to a fixed step for payroll."""

from typing import Iterable, List

from hourglass.parsing import format_span
from hourglass.models import Span

def _check_step(step_minutes: int) -> None:
    """A step must be positive and divide an hour evenly."""
    if step_minutes <= 0 or 60 % step_minutes:
        raise ValueError(f"bad step {step_minutes}")

def _snap(minutes: int, step_minutes: int) -> int:
    """Round to the nearest step, halves going up."""
    half = step_minutes // 2
    return (minutes + half) // step_minutes * step_minutes

def _snap_span(span: Span, step_minutes: int) -> Span:
    start = _snap(span.start, step_minutes)
    end = _snap(span.end, step_minutes)
    return Span(start, end)

def _label(span: Span) -> str:
    hours, minutes = divmod(span.minutes, 60)
    return f"{format_span(span)} ({hours}h {minutes}m)"

# ---
def round_spans(
    spans: Iterable[Span], step_minutes: int
) -> List[str]:
    """Snap spans to the step and label each one."""
    _check_step(step_minutes)
    snapped = [
        _snap_span(span, step_minutes) for span in spans
    ]
    return [_label(span) for span in snapped]

