# owner: platform
import unittest

from hourglass.rounding import round_spans
from hourglass.models import Span

class RoundSpansTests(unittest.TestCase):
    def test_snaps_both_edges_and_labels(self):
        spans = [Span(543, 1032)]
        self.assertEqual(
            round_spans(spans, 15), ["09:00-17:15 (8h 15m)"]
        )

    def test_halfway_points_go_up(self):
        up = round_spans([Span(555, 600)], 30)
        down = round_spans([Span(554, 600)], 30)
        self.assertEqual(up, ["09:30-10:00 (0h 30m)"])
        self.assertEqual(down, ["09:00-10:00 (1h 0m)"])

    def test_step_of_one_keeps_minutes(self):
        spans = [Span(541, 600)]
        self.assertEqual(
            round_spans(spans, 1), ["09:01-10:00 (0h 59m)"]
        )

    def test_end_of_day_survives_rounding(self):
        spans = [Span(1400, 1440)]
        self.assertEqual(
            round_spans(spans, 60), ["23:00-24:00 (1h 0m)"]
        )

    def test_keeps_order_and_handles_empty(self):
        spans = [Span(600, 660), Span(540, 570)]
        self.assertEqual(
            round_spans(spans, 30),
            ["10:00-11:00 (1h 0m)", "09:00-09:30 (0h 30m)"]
        )
        self.assertEqual(round_spans([], 15), [])

    def test_span_that_collapses_is_an_error(self):
        with self.assertRaises(ValueError):
            round_spans([Span(541, 543)], 15)

    def test_bad_steps_are_rejected(self):
        for step in (0, -15, 7, 90):
            with self.subTest(step=step):
                with self.assertRaises(ValueError):
                    round_spans([Span(540, 600)], step)
